package com.daniil.wristlens.wear;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import com.daniil.wristlens.shared.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.util.ReflectionHelpers;import java.time.Duration;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="en-rUS-w240dp-h240dp-round-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class WatchPreferencesTest {
 Activity a;
 @Before public void before(){a=Robolectric.buildActivity(Activity.class).setup().get();Strings.init(a);CopySettings.prefs(a).edit().clear().commit();ActionFeedback.enabled(a,true);}
 @After public void after(){for(Dialog d:new ArrayList<>(ShadowDialog.getShownDialogs()))d.dismiss();a.finish();}
 private RoundMenuFrame menu(int height){LinearLayout col=new LinearLayout(a);col.setOrientation(LinearLayout.VERTICAL);col.addView(new View(a),new LinearLayout.LayoutParams(100,height));ScrollView scroll=new ScrollView(a);scroll.addView(col);RoundMenuFrame root=new RoundMenuFrame(a,scroll);a.setContentView(root);RoundMenuTest.layout(root,480);return root;}
 @Test public void indicatorAppearsForScrollingThenFadesAndShortPagesStayHidden()throws Exception{RoundMenuFrame root=menu(1600);assertEquals(0f,(Float)ReflectionHelpers.getField(root,"indicatorAlpha"),0);root.rotate(2);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(180));assertTrue((Float)ReflectionHelpers.getField(root,"indicatorAlpha")>.9f);RoundMenuTest.save(root,"scroll-indicator-active");Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(1300));assertEquals(0f,(Float)ReflectionHelpers.getField(root,"indicatorAlpha"),.01f);RoundMenuTest.save(root,"scroll-indicator-idle");RoundMenuFrame shortPage=menu(20);shortPage.rotate(2);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(180));assertEquals(0f,(Float)ReflectionHelpers.getField(shortPage,"indicatorAlpha"),0);}
 @Test public void vibrationSwitchPersistsAndGatesFeedback(){try(var ctl=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity watch=ctl.get();View more=ReflectionHelpers.getField(watch,"more");more.performClick();Dialog d=ShadowDialog.getLatestDialog();GallerySettingsTest.text(d,"Vibration for actions").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(ActionFeedback.enabled(a));assertEquals("Saved",ShadowToast.getTextOfLatestToast());View button=GallerySettingsTest.text(d,"Back");assertFalse(button.isHapticFeedbackEnabled());assertFalse(ActionFeedback.perform(button,HapticFeedbackConstants.CONFIRM));d.dismiss();more.performClick();assertFalse(((CheckBox)GallerySettingsTest.text(ShadowDialog.getLatestDialog(),"Vibration for actions")).isChecked());}}

 @Test public void onlyFocusedCameraWindowKeepsScreenAwake(){try(var ctl=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity watch=ctl.get();ReflectionHelpers.setField(watch,"active",true);watch.onWindowFocusChanged(true);assertTrue((watch.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);((View)ReflectionHelpers.getField(watch,"more")).performClick();watch.onWindowFocusChanged(false);assertEquals(0,watch.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);Dialog menu=ShadowDialog.getLatestDialog();assertEquals(0,menu.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);menu.dismiss();watch.onWindowFocusChanged(true);assertTrue((watch.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);}}
 @Test public void destinationAndProfilesUseSeparateDeduplicationKeys(){var defaults=CopySettings.read(a);assertEquals("DCIM/Camera",defaults.folder());assertEquals("id",MediaClient.copyKey("id",defaults,"image/jpeg"));CopySettings.saveFolder(a,"DCIM/WristLens/Test");CopySettings.prefs(a).edit().putString("photo","compact").commit();var options=CopySettings.read(a);assertTrue(MediaClient.copyKey("id",options,"image/jpeg").endsWith(":compact"));assertTrue(MediaClient.copyKey("id",options,"video/mp4").endsWith(":original"));assertNotEquals(MediaClient.copyKey("id",options,"image/jpeg"),MediaClient.copyKey("id",defaults,"image/jpeg"));assertThrows(IllegalArgumentException.class,()->CopySettings.saveFolder(a,"DCIM/../Other"));assertEquals("DCIM/WristLens/Test",CopySettings.read(a).folder());}
 @Test public void copySettingsRemainOpenAndShowSaved()throws Exception{LinearLayout col=new LinearLayout(a);col.setOrientation(LinearLayout.VERTICAL);CopySettings.add(a,col);Dialog d=new Dialog(a);ScrollView scroll=new ScrollView(a);scroll.addView(col);Controls.show(a,d,scroll);GallerySettingsTest.views(d).stream().filter(v->v instanceof Button&&((Button)v).getText().toString().startsWith("Photo compression")).findFirst().orElseThrow().performClick();GallerySettingsTest.text(ShadowDialog.getLatestDialog(),"JPEG · 70% · up to 1280 px").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals("compact",CopySettings.read(a).photo());assertTrue(d.isShowing());assertEquals("Saved",ShadowToast.getTextOfLatestToast());RoundMenuFrame root=RoundMenuTest.frame(d);RoundMenuTest.layout(root,480);RoundMenuTest.save(root,"copy-settings");}
}
